const DICT = {
  "en": EN,
  "ar": AR,
  "bn": BN,
  "bg": BG,
  "ca": CA,
  "zh-CN": ZH_CN,
  "zh-TW": ZH_TW,
  "hr": HR,
  "cs": CS,
  "da": DA,
  "nl": NL,
  "et": ET,
  "fil": FIL,
  "fi": FI,
  "fr": FR,
  "de": DE,
  "el": EL,
  "he": HE,
  "hi": HI,
  "hu": HU,
  "is": IS,
  "id": ID,
  "ga": GA,
  "it": IT,
  "ja": JA,
  "ko": KO,
  "lv": LV,
  "lt": LT,
  "ms": MS,
  "no": NO,
  "fa": FA,
  "pl": PL,
  "pt-BR": PT_BR,
  "pt": PT,
  "ro": RO,
  "ru": RU,
  "sr": SR,
  "si": SI,
  "sk": SK,
  "sl": SL,
  "es-MX": ES,
  "sw": SW,
  "sv": SV,
  "ta": TA,
  "th": TH,
  "tr": TR,
  "uk": UK,
  "ur": UR,
  "uz": UZ,
  "vi": VI,
  "es": ES,
  "zh": ZH_CN,
};

export function resolveLang(raw) {
  const code = String(raw || "en").trim().split(".")[0].replaceAll("_", "-");
  if (DICT[code]) return code;
  if (SUPPORTED_LANGS.some((l) => l.code === code)) return code;
  const base = code.split("-")[0].toLowerCase();
  if (DICT[base]) return base;
  return "en";
}

export function currentLang() {
  const mode = shared("james.langMode") ?? "auto";
  if (mode !== "auto") return resolveLang(mode);
  return resolveLang(shared("james.lang") ?? "en");
}

export function supportedLangs() {
  return SUPPORTED_LANGS;
}

let lastPublishedLang = null;

export function publishI18n() {
  const lang = currentLang();
  if (lastPublishedLang === lang && shared("james.i18n.dict")) return;
  lastPublishedLang = lang;
  setShared("james.i18n.lang", lang);
  setShared("james.i18n.langs", SUPPORTED_LANGS);
  setShared("james.i18n.dict", { ...EN, ...(DICT[lang] ?? {}) });
}

export function tr(key, vars = null) {
  const lang = currentLang();
  let text = DICT[lang]?.[key] ?? EN[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      text = text.replaceAll(`{${k}}`, String(v ?? ""));
    }
  }
  return text;
}
